//! Parity against the old add-on's Python reference.
//!
//! `tests/fixtures/parity.json` is generated by `scripts/gen_parity_fixtures.py` from
//! `dp._solve_once_numeric` (the unchanged pure-Python reference).  For every case this test runs
//! the vendored C core through [`energy_opt::solve`] and compares:
//!
//! * the reported objective, cycle cost, terminal error and internal objective at 1e-9;
//! * every energy and power at 1e-9, every window at 1e-9, the state grid and the **whole** value
//!   function at 1e-9 (so an interior cell cannot drift unnoticed);
//! * the iteration count and the state count exactly;
//! * the per-slot decision exactly: the stored power must equal the reference one-step argmin at
//!   the grid-snapped state, bit for bit (ties resolve to the lowest power).
//!
//! The old differential used 1e-9 on paths and objectives and exact equality on decisions; that is
//! exactly the contract pinned here.

// Test code: a failed assertion is the report, so `unwrap`/`expect`/`panic!` are the intended
// API here.  The workspace policy (no panics in shipped code) applies to the library, not to the
// tests that prove it refuses.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::assert_is_empty,
    clippy::float_cmp,
    clippy::manual_midpoint
)]

use std::path::PathBuf;

use energy_opt::validate::{self, Slot};
use energy_opt::{
    BatterySpec, Config, PvChargePreference, SolveInput, SolveResult, Window, solve,
    solve_with_terminal_row,
};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct Fixture {
    reference: Reference,
    tolerance: Tolerance,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Reference {
    file: String,
    sha256: String,
    max_states: i64,
    max_iterations: i64,
}

#[derive(Debug, Deserialize)]
struct Tolerance {
    objective: f64,
    path: f64,
    value: f64,
}

#[derive(Debug, Deserialize)]
struct Case {
    name: String,
    battery: Battery,
    start_kwh: f64,
    config: CaseConfig,
    slots: Slots,
    terminal_row: Option<String>,
    expected: Expected,
}

#[derive(Debug, Deserialize)]
struct Battery {
    e_min_kwh: f64,
    e_max_kwh: f64,
    p_charge_kw: f64,
    p_discharge_kw: f64,
    eta_charge: f64,
    eta_discharge: f64,
}

#[derive(Debug, Deserialize)]
struct CaseConfig {
    slot_minutes: f64,
    soc_step_kwh: f64,
    power_steps: i64,
    allow_grid_charge: bool,
    allow_export: bool,
    max_import_kw: f64,
    max_export_kw: f64,
    min_spread_eur_per_kwh: f64,
    wear_eur_per_kwh: f64,
    salvage: f64,
    target_penalty: f64,
    max_states: i64,
    max_iterations: i64,
    refuse_battery_export: bool,
    sell_floor_eur_per_kwh: Option<f64>,
    pv_charge_preference: String,
    e_target: Option<f64>,
}

#[derive(Debug, Deserialize)]
struct Slots {
    pv_kw: Vec<f64>,
    load_kw: Vec<f64>,
    buy: Vec<f64>,
    sell: Vec<f64>,
    minutes: Vec<f64>,
}

#[derive(Debug, Deserialize)]
struct Expected {
    objective_eur: f64,
    cycle_cost_eur: f64,
    terminal_error_kwh: f64,
    internal_objective_eur: f64,
    iterations: i64,
    effective_step_kwh: f64,
    states: usize,
    energies: Vec<f64>,
    powers: Vec<f64>,
    windows: Vec<f64>,
    grid: Vec<f64>,
    value: Vec<f64>,
}

fn fixture_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/parity.json")
}

impl Case {
    fn config(&self) -> Config {
        let config = &self.config;
        Config {
            e_min_kwh: self.battery.e_min_kwh,
            e_max_kwh: self.battery.e_max_kwh,
            p_charge_kw: self.battery.p_charge_kw,
            p_discharge_kw: self.battery.p_discharge_kw,
            eta_charge: self.battery.eta_charge,
            eta_discharge: self.battery.eta_discharge,
            start_kwh: self.start_kwh,
            slot_minutes: config.slot_minutes,
            soc_step_kwh: config.soc_step_kwh,
            power_steps: config.power_steps,
            max_states: config.max_states,
            max_iterations: config.max_iterations,
            allow_grid_charge: config.allow_grid_charge,
            allow_export: config.allow_export,
            max_import_kw: config.max_import_kw,
            max_export_kw: config.max_export_kw,
            min_spread_eur_per_kwh: config.min_spread_eur_per_kwh,
            wear_eur_per_kwh: config.wear_eur_per_kwh,
            salvage: config.salvage,
            target_penalty: config.target_penalty,
            e_target: config.e_target,
            refuse_battery_export: config.refuse_battery_export,
            sell_floor_eur_per_kwh: config.sell_floor_eur_per_kwh,
            pv_charge_preference: match config.pv_charge_preference.as_str() {
                "prefer_pv" => PvChargePreference::PreferPv,
                "avoid_pv" => PvChargePreference::AvoidPv,
                _ => PvChargePreference::Auto,
            },
        }
    }

    /// The continuation row the fixture used: a smooth taper over the reference grid.
    fn terminal_row(&self, config: &Config) -> Option<Vec<f64>> {
        match self.terminal_row.as_deref() {
            None => None,
            Some("taper") => {
                let (grid, _) = validate::reference_grid(config, self.slots.pv_kw.len());
                Some(grid.iter().map(|energy| -0.04 * energy - 0.02).collect())
            }
            Some(other) => panic!("unknown terminal row kind in fixture: {other}"),
        }
    }
}

/// Absolute tolerance plus the reference's relative slack (`_fast._tol`).
fn close(got: f64, expected: f64, base: f64) -> bool {
    (got - expected).abs() <= base + 1e-12 * expected.abs()
}

fn solve_case(case: &Case, config: &Config, row: Option<&[f64]>) -> SolveResult {
    let input = SolveInput::new(
        &case.slots.pv_kw,
        &case.slots.load_kw,
        &case.slots.buy,
        &case.slots.sell,
        &case.slots.minutes,
    );
    match row {
        Some(row) => solve_with_terminal_row(&input, config, row),
        None => solve(&input, config),
    }
    .unwrap_or_else(|error| panic!("case {} failed: {error}", case.name))
}

#[test]
fn fixture_is_current() {
    let fixture: Fixture = serde_json::from_str(
        &std::fs::read_to_string(fixture_path()).expect("the parity fixture is checked in"),
    )
    .expect("the parity fixture parses");
    assert_eq!(
        fixture.reference.file, "energy_manager/app/optimize/dp.py",
        "the fixture must name the reference it came from"
    );
    assert_eq!(fixture.reference.sha256.len(), 64);
    assert_eq!(fixture.reference.max_states, 400);
    assert_eq!(fixture.reference.max_iterations, 2_000_000);
    assert_eq!(fixture.cases.len(), 20, "twenty deterministic cases");
    assert_eq!(fixture.tolerance.objective, 1e-9);
    assert_eq!(fixture.tolerance.path, 1e-9);
    assert_eq!(fixture.tolerance.value, 1e-9);
}

fn load_fixture() -> Fixture {
    serde_json::from_str(
        &std::fs::read_to_string(fixture_path()).expect("the parity fixture is checked in"),
    )
    .expect("the parity fixture parses")
}

#[test]
fn objective_and_paths_match_the_python_reference() {
    let fixture = load_fixture();
    for case in &fixture.cases {
        let config = case.config();
        let row = case.terminal_row(&config);
        let result = solve_case(case, &config, row.as_deref());
        check_scalars(case, &result, &fixture.tolerance);
        check_series(case, &result, &fixture.tolerance);
    }
}

/// The four costs, the step and the two counts.
fn check_scalars(case: &Case, result: &SolveResult, tolerance: &Tolerance) {
    let expected = &case.expected;
    let checks = [
        ("objective", result.objective_eur, expected.objective_eur),
        ("cycle cost", result.cycle_cost_eur, expected.cycle_cost_eur),
        (
            "terminal error",
            result.terminal_error_kwh,
            expected.terminal_error_kwh,
        ),
        (
            "internal objective",
            result.internal_objective_eur,
            expected.internal_objective_eur,
        ),
        (
            "step",
            result.effective_step_kwh,
            expected.effective_step_kwh,
        ),
    ];
    for (what, got, want) in checks {
        assert!(
            close(got, want, tolerance.objective),
            "{}: {what} {got} != {want}",
            case.name
        );
    }
    assert_eq!(result.iterations, expected.iterations, "{}", case.name);
    assert_eq!(result.states, expected.states, "{}", case.name);
}

/// Every reported series, against the Python reference.
fn check_series(case: &Case, result: &SolveResult, tolerance: &Tolerance) {
    let expected = &case.expected;
    assert_eq!(result.grid.len(), expected.grid.len(), "{}", case.name);
    for (index, (got, want)) in result.grid.iter().zip(&expected.grid).enumerate() {
        assert!(
            close(*got, *want, tolerance.value),
            "{}: grid[{index}] {got} != {want}",
            case.name
        );
    }
    for (index, (got, want)) in result.energies.iter().zip(&expected.energies).enumerate() {
        assert!(
            close(*got, *want, tolerance.path),
            "{}: energies[{index}] {got} != {want}",
            case.name
        );
    }
    for (index, (got, want)) in result.powers.iter().zip(&expected.powers).enumerate() {
        assert!(
            close(*got, *want, tolerance.path),
            "{}: powers[{index}] {got} != {want}",
            case.name
        );
    }
    let windows: Vec<f64> = result.windows.iter().flat_map(Window::values).collect();
    for (index, (got, want)) in windows.iter().zip(&expected.windows).enumerate() {
        assert!(
            close(*got, *want, tolerance.value),
            "{}: windows[{index}] {got} != {want}",
            case.name
        );
    }
    assert_eq!(result.value.len(), expected.value.len(), "{}", case.name);
    for (index, (got, want)) in result.value.iter().zip(&expected.value).enumerate() {
        assert!(
            close(*got, *want, tolerance.value),
            "{}: value[{index}] {got} != {want}",
            case.name
        );
    }
}

#[test]
fn decisions_match_the_reference_argmin_exactly() {
    let fixture = load_fixture();
    for case in &fixture.cases {
        check_decisions(case);
    }
}

/// Every stored power against the reference one-step argmin at the grid-snapped state.
fn check_decisions(case: &Case) {
    let config = case.config();
    let row = case.terminal_row(&config);
    let result = solve_case(case, &config, row.as_deref());
    let n = result.powers.len();
    let states = result.states;
    let mut energy = validate::clamp(config.start_kwh, config.e_min_kwh, config.e_max_kwh);
    for i in 0..n {
        let slot = Slot {
            pv_kw: case.slots.pv_kw[i],
            load_kw: case.slots.load_kw[i],
            buy: case.slots.buy[i],
            sell: case.slots.sell[i],
            minutes: case.slots.minutes[i],
        };
        let dt = slot.minutes / 60.0;
        let (lo, hi) = validate::bounds(&config, &slot, energy, dt);
        // The stored decision is taken at the grid point the state snaps to.
        let mut state = energy;
        let mut action_lo = lo;
        let mut action_hi = hi;
        if let Some(point) = result
            .grid
            .iter()
            .find(|point| (**point - energy).abs() <= validate::EPS_KWH)
        {
            state = *point;
            (action_lo, action_hi) = validate::bounds(&config, &slot, state, dt);
        }
        let extra = match (i + 1 == n, config.e_target) {
            (true, Some(target)) => Some(validate::exact_power(&config, state, target, dt)),
            _ => None,
        };
        let next_row = &result.value[(i + 1) * states..(i + 2) * states];
        let context = validate::SlotContext::new(&config, slot, dt, next_row, &result.grid);
        let (choice, _cost) = validate::argmin_at(&context, state, action_lo, action_hi, extra)
            .expect("the reference action set is not empty");
        let expected = validate::clamp(choice, lo, hi);
        assert_eq!(
            result.powers[i], expected,
            "{}: slot {i} returned {} but the reference argmin is {expected}",
            case.name, result.powers[i]
        );
        energy = validate::clamp(
            validate::next_energy(&config, energy, result.powers[i], dt),
            config.e_min_kwh,
            config.e_max_kwh,
        );
    }
}

#[test]
fn the_core_build_is_not_stale() {
    energy_opt::verify_core_build().expect("the C artifact was built from the shipped sources");
    assert_eq!(
        energy_opt::core_build_sha(),
        &energy_opt::CORE_SOURCE_SHA256[..16],
        "the compiled-in digest is the digest of the C sources"
    );
    assert_eq!(energy_opt::CORE_BUILD_SHA, energy_opt::core_build_sha());
}

#[test]
fn a_minimal_solve_mirrors_the_reference_helpers() {
    // One slot, no decision: a hold can be verified by hand.
    let config = Config::new(
        BatterySpec {
            e_min_kwh: 0.5,
            e_max_kwh: 9.5,
            p_charge_kw: 3.0,
            p_discharge_kw: 3.0,
            eta_charge: 0.95,
            eta_discharge: 0.95,
        },
        4.0,
    );
    // With no wear and no salvage, exporting 5 ct/kWh beats holding: the whole pack is worth
    // selling, so the single slot discharges at the power limit.
    let input = SolveInput::new(&[0.0], &[0.0], &[0.3], &[0.05], &[60.0]);
    let result = solve(&input, &config).expect("a one-slot solve succeeds");
    assert_eq!(result.energies, vec![4.0]);
    assert_eq!(result.powers, vec![-3.0]);
    assert!((result.objective_eur - -0.15).abs() < 1e-12);
    assert_eq!(result.states, result.grid.len());
    assert_eq!(result.value.len(), 2 * result.states);
    assert_eq!(result.windows[0].grid_lo_kw, -3.0);
    assert_eq!(result.windows[0].grid_hi_kw, 3.0);
}
